window.VeilGardeData.files["Tests-VeilGardeLensTests"] = {"group":"Tests-VeilGardeLensTests","files":[{"path":"Tests/VeilGardeLensTests/CLIPParityTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,44]],"header":{"lines":[1,9],"target":"VeilGardeLensTests","what":[6,8],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1376,"scopes":[["X","LensMLXSuites",null,"",17,17,[17,24],44,null,-1,0,"a"],["S","CLIPParity",null,"",18,19,[19,22],43,null,0,0,"a"],["v","weights",null,"static",22,22,[22,33],25,[21,21],1,0,"a"],["f","parity",[],"",27,28,[28,29],42,null,1,0,"a"]],"old":"","new":"//\n//  CLIPParityTests.swift\n//  VeilGardeLensTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The CLIP vision tower against Hugging Face's on the same pixels: every image's\n//        embedding within cosine 0.9999, and the router's category call (the argmax over its\n//        five prompts) the same. Skipped when the weights are not on this Mac.\n//\n\nimport Foundation\nimport MLX\nimport Testing\nimport VeilGardeCore\n@testable import VeilGardeLens\n\nextension LensMLXSuites {\n    @Suite(\"CLIP vision against Hugging Face\", .serialized)\n    struct CLIPParity {\n        static let fixture = Fixture.url(\"clip_parity.safetensors\")\n        /// The work area's weights folder holds the tower (`veilgarde weights import-clip`).\n        static var weights: URL? {\n            if let area = WorkArea.resolve() { WeightLocator.shared.register(area.root.appendingPathComponent(\"weights\", isDirectory: true)) }\n            return WeightLocator.shared.url(.clipVision)\n        }\n\n        @Test(\"embeddings within cosine 0.9999 of HF's, categories equal\", .enabled(if: weights != nil))\n        func parity() throws {\n            let f = try SafetensorsFile(url: Self.fixture)\n            let pixels = try f.uint8(\"pixels\"), expected = try f.float32(\"embeds\"), logits = try f.float32(\"logits\")\n            let n = try f.tensor(\"pixels\").shape[0]\n            let ours = try CLIPLens.shared.tower()(CLIPPreprocess.input(pixels: pixels, count: n)).asArray(Float.self)\n            let prompts = try SafetensorsFile(url: Fixture.repoRoot.appendingPathComponent(\"Sources/VeilGardeFlywheel/Resources/clip_prompts_v1.safetensors\")).float32(\"prompts\")\n            for i in 0..<n {\n                let a = Array(ours[(i * 512)..<((i + 1) * 512)]), b = Array(expected[(i * 512)..<((i + 1) * 512)])\n                let cos = zip(a, b).reduce(Float(0)) { $0 + $1.0 * $1.1 }\n                #expect(cos >= 0.9999, \"image \\(i): cosine \\(cos)\")\n                let mine = (0..<5).map { k in 100 * zip(a, prompts[(k * 512)..<((k + 1) * 512)]).reduce(Float(0)) { $0 + $1.0 * $1.1 } }\n                let theirs = Array(logits[(i * 13)..<(i * 13 + 5)])\n                #expect(mine.firstIndex(of: mine.max()!) == theirs.firstIndex(of: theirs.max()!), \"image \\(i): category\")\n            }\n        }\n    }\n}\n"},{"path":"Tests/VeilGardeLensTests/Fixture.swift","status":"added","lang":"swift","hunks":[[1,0,1,21]],"header":{"lines":[1,8],"target":"VeilGardeLensTests","what":[6,7],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1380,"scopes":[["E","Fixture",null,"",12,12,[12,13],21,null,-1,0,"a",[]],["f","url",["_"],"static",19,19,[19,43],19,null,0,8,"a"],["f","resource",["_"],"static",20,20,[20,48],20,null,0,8,"a"]],"old":"","new":"//\n//  Fixture.swift\n//  VeilGardeLensTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: Paths the Lens tests read by repo path: their own fixtures (the CLIP parity file), and the\n//        shipped resources.\n//\n\nimport Foundation\n\nenum Fixture {\n    static let repoRoot: URL = {\n        var url = URL(fileURLWithPath: #filePath)\n        while url.lastPathComponent != \"Tests\" { url.deleteLastPathComponent() }\n        return url.deletingLastPathComponent()\n    }()\n\n    static func url(_ name: String) -> URL { repoRoot.appendingPathComponent(\"Tests/VeilGardeLensTests/Fixtures/\\(name)\") }\n    static func resource(_ name: String) -> URL { repoRoot.appendingPathComponent(\"Sources/VeilGardeInference/Resources/\\(name)\") }\n}\n"},{"path":"Tests/VeilGardeLensTests/LinkTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,15]],"header":{"lines":[1,7],"target":"VeilGardeLensTests","what":[6,6],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1383,"scopes":[["S","LensLinkTests",null,"",12,13,[13,21],15,null,-1,0,"a"],["f","reExportsCore",[],"",14,14,[14,31],14,null,0,8,"a"]],"old":"","new":"//\n//  LinkTests.swift\n//  VeilGardeLensTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The module links and re-exports Core.\n//\n\nimport Testing\nimport VeilGardeLens\n\n@Suite(\"Lens links\")\nstruct LensLinkTests {\n    @Test func reExportsCore() { #expect(!VeilGardeVersion.string.isEmpty) }\n}\n"},{"path":"Tests/VeilGardeLensTests/MLXGate.swift","status":"added","lang":"swift","hunks":[[1,0,1,21]],"header":{"lines":[1,10],"target":"VeilGardeLensTests","what":[6,9],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1385,"scopes":[["S","LensMLXSuites",null,"",20,21,[21,21],21,null,-1,8,"a"]],"old":"","new":"//\n//  MLXGate.swift\n//  VeilGardeLensTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The MLX suites run one at a time and only when asked: VEILGARDE_MLX_TESTS=1 (or\n//        FRIGATE_MLX_TESTS=1). Every GPU suite in this target nests under LensMLXSuites, which\n//        is serialized; run the targets with `swift test --no-parallel` too, so two MLX workloads\n//        never overlap.\n//\n\nimport Foundation\nimport Testing\n\nlet mlxTests: Bool = {\n    let env = ProcessInfo.processInfo.environment\n    return env[\"VEILGARDE_MLX_TESTS\"] == \"1\" || env[\"FRIGATE_MLX_TESTS\"] == \"1\"\n}()\n\n@Suite(\"Lens: MLX, one suite at a time\", .enabled(if: mlxTests), .serialized)\nstruct LensMLXSuites {}\n"},{"path":"Tests/VeilGardeLensTests/ScorerTests.swift","status":"added","lang":"swift","hunks":[[1,0,1,67]],"header":{"lines":[1,9],"target":"VeilGardeLensTests","what":[6,8],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1386,"scopes":[["S","ScorerTests",null,"",18,19,[19,19],67,null,-1,0,"a"],["f","evaluatorsAgree",[],"",20,21,[21,34],30,null,0,0,"a"],["f","orientedPNG",["_"],"",33,33,[33,56],45,[32,32],0,0,"a"],["f","rgb",["_"],"",47,47,[47,42],53,null,0,0,"a"],["f","orientation",[],"",55,56,[56,30],66,null,0,0,"a"]],"old":"","new":"//\n//  ScorerTests.swift\n//  VeilGardeLensTests\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: Frigate's XGBoostTreeModel (what the detector scores with) and Core's GBDTModel (what the\n//        trainer writes and evaluates) agree bit for bit on the shipped camera head, missing values\n//        included; the decoder applies EXIF orientation as NSImage does.\n//\n\nimport CoreGraphics\nimport Foundation\nimport ImageIO\nimport Testing\nimport UniformTypeIdentifiers\n@testable import VeilGardeLens\n\n@Suite(\"Scorers and decoding\")\nstruct ScorerTests {\n    @Test(\"Frigate's evaluator and GBDTModel agree bit for bit on the shipped camera head\")\n    func evaluatorsAgree() throws {\n        let url = Fixture.resource(\"camera.xgb.json\")\n        let frigate = try TreeModelCache.shared.model(url)\n        let core = try GBDTModel.load(url)\n        #expect(frigate.numFeatures == core.featureCount)\n        var rng = SplitMix64(seed: 7)\n        var rows = (0..<32).map { _ in (0..<core.featureCount).map { _ in Float(rng.unit() * 4 - 2) } }\n        for i in stride(from: 0, to: rows.count, by: 4) { rows[i][384] = .nan; rows[i][0] = .nan }   // missing values go their default way\n        #expect(frigate.predictBatch(rows) == core.scoreBatch(rows))\n    }\n\n    /// A 3×2 image whose pixels are all distinct, written with an EXIF orientation tag.\n    func orientedPNG(_ orientation: Int) throws -> Data {\n        var pixels = [UInt8]()\n        for i in 0..<6 { pixels += [UInt8(40 * i), UInt8(255 - 40 * i), UInt8(17 * i), 255] }\n        let provider = CGDataProvider(data: Data(pixels) as CFData)!\n        let image = CGImage(width: 3, height: 2, bitsPerComponent: 8, bitsPerPixel: 32, bytesPerRow: 12, space: CGColorSpace(name: CGColorSpace.sRGB)!,\n                            bitmapInfo: CGBitmapInfo(rawValue: CGImageAlphaInfo.premultipliedLast.rawValue), provider: provider, decode: nil,\n                            shouldInterpolate: false, intent: .defaultIntent)!\n        let data = NSMutableData()\n        let destination = CGImageDestinationCreateWithData(data as CFMutableData, UTType.png.identifier as CFString, 1, nil)!\n        CGImageDestinationAddImage(destination, image, [kCGImagePropertyOrientation: orientation] as CFDictionary)\n        #expect(CGImageDestinationFinalize(destination))\n        return data as Data\n    }\n\n    func rgb(_ image: CGImage) -> [UInt8] {\n        var buffer = [UInt8](repeating: 0, count: image.width * image.height * 4)\n        let ctx = CGContext(data: &buffer, width: image.width, height: image.height, bitsPerComponent: 8, bytesPerRow: image.width * 4,\n                            space: CGColorSpaceCreateDeviceRGB(), bitmapInfo: CGImageAlphaInfo.noneSkipLast.rawValue)!\n        ctx.draw(image, in: CGRect(x: 0, y: 0, width: image.width, height: image.height))\n        return buffer\n    }\n\n    @Test(\"orientation 6 rotates clockwise and 1 leaves the pixels alone\")\n    func orientation() throws {\n        let upright = try ImageDecoding.cgImage(data: orientedPNG(1))\n        #expect(upright.width == 3 && upright.height == 2)\n        let rotated = try ImageDecoding.cgImage(data: orientedPNG(6))\n        #expect(rotated.width == 2 && rotated.height == 3)\n        let a = rgb(upright), b = rgb(rotated)\n        // Rotating 90° clockwise: the stored top-left (0,0) lands at the top-right of a 2-wide image.\n        #expect(Array(b[4..<7]) == Array(a[0..<3]))\n        // The stored bottom-left (0,1) lands at the top-left.\n        #expect(Array(b[0..<3]) == Array(a[12..<15]))\n    }\n}\n"}]};
